<template>
 <section class="performance-panel">
  <header><h2>Rendimiento y evaluación del equipo de soporte</h2><button :disabled="!data || dirty || loading" @click="exportReport">Exportar indicadores CSV</button></header>
  <form @submit.prevent="load" class="performance-filters"><label>Desde<input type="date" v-model="filters.from" required></label><label>Hasta<input type="date" v-model="filters.to" required></label><label>Programador / usuario<select v-model="filters.user"><option value="">Todo el equipo</option><option v-for="u in context.usuarios" :key="u.Usuario" :value="u.Usuario">{{u.NombreUsuario || u.Usuario}} · {{u.Usuario}}</option></select></label><button :disabled="loading">{{loading?'Consultando…':'Consultar rendimiento'}}</button></form>
  <p v-if="error" role="alert" class="performance-warning">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="dirty" class="performance-warning">Los filtros cambiaron. Consulta para actualizar.</p>
  <template v-if="data"><p>Del {{data.from}} al {{data.to}} · Hora de Lima · Incluye historial archivado. La primera respuesta humana y las soluciones se atribuyen a quien las registró; el tiempo corresponde a los registros de trabajo que se cruzan con este período.</p>
   <p v-if="data.unattributed_responses" class="performance-warning">{{data.unattributed_responses}} primeras respuestas históricas no tienen autor confirmado. Se conservan en los tickets y no se atribuyen a un programador en esta comparación.</p>
   <div class="performance-charts"><section><h3>Participación en el tiempo de soporte registrado</h3><div class="performance-canvas"><canvas ref="pie" aria-label="Distribución de minutos de soporte por usuario" role="img"></canvas></div><p v-if="!totalMinutes">No hay tiempo registrado para este período.</p><small>Minutos declarados en los registros de trabajo. Revisa complejidad, calidad y evidencias para evaluar dedicación.</small></section><section><h3>Soluciones y pendientes por usuario</h3><div class="performance-canvas"><canvas ref="bars" aria-label="Soluciones y pendientes por usuario" role="img"></canvas></div><small>Pendientes: estado actual de tickets creados en el rango. Soluciones: eventos de resolución registrados en el rango; una reapertura puede producir otro evento.</small></section></div>
   <div class="performance-scroll"><table><thead><tr><th>Usuario</th><th>Tickets creados en el rango y asignados</th><th>Pendientes</th><th>Atendidos</th><th>Soluciones registradas</th><th>Trabajo registrado</th><th>Primera respuesta humana promedio</th><th>Tiempo creación a solución promedio</th><th>Calificación del cliente</th><th></th></tr></thead><tbody><tr v-for="p in data.team" :key="p.id"><td>{{p.user}}</td><td>{{p.assigned}}</td><td>{{p.pending}}</td><td>{{p.attended}}</td><td>{{p.resolved_events}}</td><td>{{minutes(p.work_minutes)}}<small>{{p.worklogs}} registros</small></td><td>{{average(p.response_average)}}<small>{{p.response_count}} respuestas con autor confirmado</small></td><td>{{average(p.resolution_average)}}<small>{{p.resolution_count}} eventos</small></td><td>{{p.rating===null?'Sin calificar':p.rating+' / 5'}}<small>{{p.ratings}} opiniones</small></td><td><button @click="evaluate(p)">Evaluar</button></td></tr><tr v-if="!data.team.length"><td colspan="10">Sin usuarios con acceso o actividad de soporte en esta selección.</td></tr></tbody></table></div>
   <details open><summary>Avances diarios por programador · tareas y soporte</summary><button @click="exportDaily" :disabled="dirty || loading">Exportar cuadro diario CSV</button><div class="performance-scroll"><table><thead><tr><th>Fecha</th><th>Usuario que registró el avance</th><th>Avances internos</th><th>Tareas concluidas</th><th>Soporte registrado</th><th>Primeras respuestas</th><th>Soluciones registradas</th></tr></thead><tbody><tr v-for="d in orderedDaily" :key="d.date+':'+d.user"><td>{{d.date}}</td><td>{{d.user}}</td><td>{{d.internal_updates}}</td><td>{{d.internal_done}}</td><td>{{minutes(d.work_minutes)}}</td><td>{{d.response_count}}</td><td>{{d.resolved_events}}</td></tr><tr v-if="!orderedDaily.length"><td colspan="7">No hay avances registrados en el rango.</td></tr></tbody></table></div></details>
   <details><summary>Evidencias de avances de tareas internas</summary><p v-if="internal.limitado" class="performance-warning">Se muestran los 500 avances más recientes; el cuadro diario incluye todos. Reduce el rango para revisar el detalle.</p><div class="performance-scroll"><table><thead><tr><th>Fecha</th><th>Tarea</th><th>Autor</th><th>Avance</th></tr></thead><tbody><tr v-for="e in internal.avances" :key="e.Id"><td>{{e.Fecha}}</td><td><button @click="openInternal(e.tarea)">{{e.Ticket || e.Titulo}}</button></td><td>{{e.Usuario}}</td><td class="performance-evidence">{{e.Texto || e.Accion}}</td></tr></tbody></table></div></details>
   <details><summary>Evidencias del trabajo registrado ({{data.evidence_total}})</summary><p v-if="data.evidence_limited" class="performance-warning">Se muestran las 2000 evidencias más recientes. Reduce el rango para revisar el detalle; los indicadores incluyen todos los registros.</p><div class="performance-scroll"><table><thead><tr><th>Fecha</th><th>Ticket</th><th>Usuario</th><th>Minutos del período</th><th>Trabajo realizado</th></tr></thead><tbody><tr v-for="(e,index) in data.evidence" :key="index"><td>{{e.date}}</td><td><button @click="$router.push({path:'/soporte',query:{ticket:String(e.ticket_id)}})">{{e.code}}</button></td><td>{{e.user}}</td><td>{{e.minutes}}</td><td class="performance-evidence">{{e.description}}</td></tr></tbody></table></div></details>
   <section v-if="review.person" class="performance-review"><h3>Evaluación manual: {{review.person.user}}</h3><p>Los indicadores se guardarán con la evaluación para conservar su contexto. La propuesta requiere revisión del superadmin.</p><form @submit.prevent="saveReview"><label>Calificación del superadmin<select v-model.number="review.score" required><option value="">Seleccionar</option><option v-for="n in 5" :key="n" :value="n">{{n}} / 5</option></select></label><label>Propuesta<select v-model="review.proposal"><option value="development">Plan de mejora</option><option value="recognition">Reconocimiento</option><option value="raise_review">Revisar aumento</option><option value="promotion_review">Revisar ascenso</option></select></label><label>Criterios aplicados<textarea v-model="review.criteria" maxlength="3000" required rows="3" placeholder="Calidad, cumplimiento, respuesta, complejidad y evidencias revisadas"></textarea></label><label>Justificación y evidencias de la evaluación<textarea v-model="review.reason" maxlength="5000" required rows="4"></textarea></label><button :disabled="saving || dirty">{{saving?'Guardando…':'Guardar evaluación del período'}}</button><button type="button" @click="review.person=null">Cancelar</button></form></section>
   <section class="performance-review"><h3>Satisfacción de los clientes</h3><p>Opiniones recibidas en el rango y usuario consultados. Satisfecho: 4–5 estrellas; neutral: 3; insatisfecho: 1–2. Los porcentajes se calculan sobre las opiniones recibidas.</p>
    <div class="satisfaction-kpis"><strong>{{satisfaction.summary.total || 0}} opiniones<small>{{satisfaction.summary.customers || 0}} clientes distintos</small></strong><strong>{{satisfaction.summary.satisfied || 0}} satisfechos<small>{{satisfactionPercent('satisfied')}}</small></strong><strong>{{satisfaction.summary.neutral || 0}} neutrales<small>{{satisfactionPercent('neutral')}}</small></strong><strong>{{satisfaction.summary.dissatisfied || 0}} insatisfechos<small>{{satisfactionPercent('dissatisfied')}}</small></strong></div>
    <div class="performance-canvas"><canvas ref="satisfactionChart" role="img" aria-label="Satisfacción de clientes por estrellas"></canvas></div>
    <div class="performance-scroll"><table><thead><tr><th>Programador</th><th>Opiniones</th><th>Satisfechos</th><th>Neutrales</th><th>Insatisfechos</th><th>Promedio</th><th>Solución validada</th><th>Recomiendan</th></tr></thead><tbody><tr v-for="u in satisfaction.users" :key="u.id || 'unknown'"><td>{{u.user}}</td><td>{{u.total}}</td><td>{{u.satisfied}}</td><td>{{u.neutral}}</td><td>{{u.dissatisfied}}</td><td>{{u.average}} / 5</td><td>{{u.solved}} / {{u.total}}</td><td>{{u.recommend}} / {{u.total}}</td></tr></tbody></table></div>
    <button @click="exportSatisfaction" :disabled="loading || dirty">Exportar todas las opiniones CSV</button>
    <div class="performance-scroll"><table><thead><tr><th>Fecha</th><th>Cliente / empresa</th><th>Ticket</th><th>Programador</th><th>Estrellas</th><th>Validación</th><th>Comentario</th></tr></thead><tbody><tr v-for="r in satisfaction.rows" :key="r.id"><td>{{r.created_at}}</td><td>{{r.customer}}<small>{{r.company}}</small></td><td><button @click="$router.push({path:'/soporte',query:{ticket:String(r.ticket_id)}})">{{r.code}}</button><small>Ciclo {{r.cycle}}</small></td><td>{{r.user}}</td><td>{{r.stars}} / 5</td><td>{{Number(r.solved)?'Solución confirmada':'Sin confirmar'}}</td><td class="performance-evidence">{{r.comment || 'Sin comentario'}}</td></tr><tr v-if="!satisfaction.rows.length"><td colspan="7">Sin opiniones en este período.</td></tr></tbody></table></div><button v-if="satisfaction.next" @click="moreSatisfaction" :disabled="loading || dirty">Cargar más opiniones</button>
   </section>
   <details open><summary>Evaluaciones del período</summary><article v-for="r in data.reviews" :key="r.id" class="performance-review"><strong>{{r.review.user}} · {{r.review.score}} / 5 · {{proposal(r.review.proposal)}}</strong><p>{{r.review.criteria}}</p><p class="performance-evidence">{{r.review.reason}}</p><small>{{r.reviewer}} · {{r.created_at}} · Indicadores conservados: {{r.review.indicators.resolved_events}} soluciones, {{r.review.indicators.work_minutes}} min, {{average(r.review.indicators.response_average)}} de primera respuesta.</small></article><p v-if="!data.reviews.length">Sin evaluaciones registradas para este período.</p></details>
  </template>
 </section>
</template>
<script>
import config from '@/store/config';
import Chart from 'chart.js';
import {limaInput} from '@/utils/diario';
export default {props:{context:{type:Object,required:true}},data(){const today=limaInput().slice(0,10);return {filters:{from:today.slice(0,7)+'-01',to:today,user:''},applied:null,data:null,internal:{por_usuario:[],avances:[]},loading:false,saving:false,error:'',notice:'',csrf:'',review:{person:null,score:'',proposal:'development',criteria:'',reason:''}};},computed:{satisfaction(){return this.data&&this.data.satisfaction||{summary:{},users:[],rows:[],next:null};},dirty(){return this.applied&&JSON.stringify(this.applied)!==JSON.stringify(this.filters);},totalMinutes(){return this.data?this.data.team.reduce((n,p)=>n+Number(p.work_minutes),0):0;},orderedDaily(){if(!this.data)return [];const days={};const add=(date,user)=>{const key=date+':'+user;if(!days[key])days[key]={date,user,work_minutes:0,response_count:0,resolved_events:0,internal_updates:0,internal_done:0};return days[key];};this.data.daily.forEach(d=>Object.assign(add(d.date,d.user),d));(this.internal.por_usuario||[]).forEach(d=>{const row=add(d.fecha,d.usuario);row.internal_updates=Number(d.avances);row.internal_done=Number(d.concluidas);});return Object.values(days).sort((a,b)=>b.date.localeCompare(a.date)||a.user.localeCompare(b.user));}},mounted(){this.load();},beforeDestroy(){this.destroyCharts();},methods:{
 minutes(n){const total=Math.round(Number(n)||0);return Math.floor(total/60)+' h '+total%60+' min';},average(n){return n===null||n===undefined?'Sin datos':Number(n).toFixed(2)+' min';},proposal(p){return {development:'Plan de mejora',recognition:'Reconocimiento',raise_review:'Revisar aumento',promotion_review:'Revisar ascenso'}[p]||p;},failure(e){return e.response&&e.response.data&&e.response.data.error||'No se pudo consultar el rendimiento.';},
 async load(){if(this.loading||!this.context.superadmin)return;this.loading=true;this.error='';const filters=Object.assign({},this.filters);try{const results=await Promise.all([this.axios.get(config.API+'support/performance',{params:filters,timeout:30000}),this.axios.get(config.API+'diario/avances',{params:{desde:filters.from,hasta:filters.to,vista:'equipo',responsable:filters.user?'u:'+filters.user:''},timeout:30000})]);this.data=results[0].data;this.internal=results[1].data;this.applied=filters;this.review.person=null;await this.$nextTick();this.draw();}catch(e){this.error=this.failure(e);}finally{this.loading=false;}},
 destroyCharts(){if(this._pie)this._pie.destroy();if(this._bars)this._bars.destroy();if(this._satisfaction)this._satisfaction.destroy();},draw(){this.destroyCharts();if(!this.data)return;const team=this.data.team;const colors=['#1d76b9','#0c9c88','#e8b345','#8a62c7','#de6d66','#4d9fa8','#667ba8'];const options={responsive:true,maintainAspectRatio:false,animation:{duration:0},legend:{position:'bottom'}};this._satisfaction=new Chart(this.$refs.satisfactionChart,{type:'doughnut',data:{labels:['Satisfechos (4-5)','Neutrales (3)','Insatisfechos (1-2)'],datasets:[{data:['satisfied','neutral','dissatisfied'].map(k=>Number(this.satisfaction.summary[k])||0),backgroundColor:['#0c9c88','#e8b345','#d65d68']}]},options});this._pie=new Chart(this.$refs.pie,{type:'pie',data:{labels:team.map(p=>p.user),datasets:[{data:team.map(p=>p.work_minutes),backgroundColor:team.map((p,i)=>colors[i%colors.length])}]},options});this._bars=new Chart(this.$refs.bars,{type:'bar',data:{labels:team.map(p=>p.user),datasets:[{label:'Soluciones registradas',data:team.map(p=>p.resolved_events),backgroundColor:'#0c9c88'},{label:'Pendientes',data:team.map(p=>p.pending),backgroundColor:'#e8b345'}]},options:Object.assign({},options,{scales:{yAxes:[{ticks:{beginAtZero:true,precision:0}}]}})});},
 evaluate(p){this.review={person:p,score:'',proposal:'development',criteria:'',reason:''};this.$nextTick(()=>{const form=this.$el.querySelector('.performance-review form');if(form)form.scrollIntoView({behavior:'smooth',block:'center'});});},
 async saveReview(){if(this.saving||this.dirty)return;this.saving=true;this.error='';try{if(!this.csrf)this.csrf=(await this.axios.get(config.API+'support/context',{timeout:15000})).data.csrf;await this.axios.post(config.API+'support/performance_review',Object.assign({},this.applied,{principal:this.review.person.id,score:this.review.score,proposal:this.review.proposal,criteria:this.review.criteria,reason:this.review.reason}),{headers:{'X-Support-CSRF':this.csrf},timeout:30000});this.notice='Evaluación guardada con responsable, fecha e indicadores del período.';await this.load();}catch(e){this.error=this.failure(e);}finally{this.saving=false;}},
 satisfactionPercent(key){return Number(this.satisfaction.summary.total)?(100*Number(this.satisfaction.summary[key]||0)/Number(this.satisfaction.summary.total)).toFixed(1)+'%':'Sin opiniones';},
 async moreSatisfaction(){this.loading=true;try{const r=(await this.axios.get(config.API+'support/satisfaction',{params:Object.assign({},this.applied,{before:this.satisfaction.next}),timeout:20000})).data;this.data.satisfaction.rows=this.satisfaction.rows.concat(r.rows);this.data.satisfaction.next=r.next;}catch(e){this.error=this.failure(e);}finally{this.loading=false;}},
 async exportSatisfaction(){this.loading=true;try{let rows=[],before=null;do{const r=(await this.axios.get(config.API+'support/satisfaction',{params:Object.assign({},this.applied,before?{before}:{}),timeout:20000})).data;rows=rows.concat(r.rows);if(r.next&&String(r.next)===String(before))throw Error('No se pudo avanzar de pagina.');before=r.next;}while(before);const safe=v=>'"'+String(v==null?'':v).replace(/^[\s]*[=+@-]/,"'$&").replace(/"/g,'""')+'"';const lines=[['Fecha','Cliente','Empresa','Ticket','Ciclo','Programador','Estrellas','Rapidez','Trato','Solucion confirmada','Recomienda','Comentario']].concat(rows.map(r=>[r.created_at,r.customer,r.company,r.code,r.cycle,r.user,r.stars,r.speed,r.treatment,r.solved,r.recommend,r.comment]));const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='satisfaccion-'+this.applied.from+'-'+this.applied.to+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);this.notice=rows.length+' opiniones exportadas.';}catch(e){this.error=this.failure(e);}finally{this.loading=false;}},
 async openInternal(id){try{const result=await this.axios.get(config.API+'diario/tareas/'+id,{timeout:15000});this.$emit('open',result.data);}catch(e){this.error=this.failure(e);}},
 exportDaily(){const safe=v=>'"'+String(v==null?'':v).replace(/^[\s]*[=+@-]/,"'$&").replace(/"/g,'""')+'"';const lines=[['Fecha','Usuario','Avances internos','Tareas concluidas','Minutos soporte','Primeras respuestas','Soluciones']].concat(this.orderedDaily.map(d=>[d.date,d.user,d.internal_updates,d.internal_done,d.work_minutes,d.response_count,d.resolved_events]));const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='avances-diarios-'+this.applied.from+'-'+this.applied.to+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
 exportReport(){const safe=v=>'"'+String(v==null?'':v).replace(/^[\s]*[=+@-]/,"'$&").replace(/"/g,'""')+'"';const lines=[['Desde','Hasta','Usuario','Tickets creados y asignados','Pendientes','Atendidos','Soluciones del período','Minutos registrados','Respuestas con autor','Primera respuesta promedio (min)','Creación a solución promedio (min)','Calificación cliente','Opiniones']].concat(this.data.team.map(p=>[this.applied.from,this.applied.to,p.user,p.assigned,p.pending,p.attended,p.resolved_events,p.work_minutes,p.response_count,p.response_average,p.resolution_average,p.rating,p.ratings]));const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='rendimiento-'+this.applied.from+'-'+this.applied.to+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
}};
</script>
<style scoped>
.performance-panel{background:#fff;border:1px solid #c7d9e6;border-radius:16px;padding:22px;margin:18px 0;color:#193c52}.performance-panel header,.performance-filters{display:flex;flex-wrap:wrap;gap:12px;align-items:end;justify-content:space-between}.performance-panel h2{font-size:23px}.performance-filters{justify-content:flex-start;margin:16px 0}.performance-panel label{display:grid;gap:6px;font-weight:600}.performance-panel input,.performance-panel select,.performance-panel textarea,.performance-panel button{padding:9px 12px;border:1px solid #bdd0df;border-radius:8px;background:white;color:#194d69}.performance-panel button{font-weight:600}.performance-panel button:disabled{opacity:.5}.performance-charts{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}.performance-charts h3{font-size:18px}.performance-canvas{height:280px}.performance-scroll{overflow:auto;max-height:430px;margin:18px 0}.performance-panel table{width:100%;border-collapse:collapse;font-size:14px}.performance-panel th,.performance-panel td{padding:11px;border-bottom:1px solid #d9e5ee;text-align:left}.performance-panel th{background:#edf4f8;position:sticky;top:0}.performance-panel small{display:block;color:#526f83}.performance-warning{background:#fff1d8;padding:12px;border-radius:8px}.performance-evidence{white-space:pre-wrap;min-width:230px}.performance-review{background:#f0f6fa;padding:18px;border:1px solid #d3e0ea;border-radius:10px;margin:16px 0}.satisfaction-kpis{display:flex;flex-wrap:wrap;gap:18px;margin:16px 0}.satisfaction-kpis>strong{padding:14px;background:white;border-radius:8px;flex:1;min-width:130px}.performance-review form{display:grid;gap:14px}.performance-panel details{margin-top:18px}.performance-panel summary{cursor:pointer;font-weight:700}@media(max-width:700px){.performance-panel{padding:12px}.performance-charts{grid-template-columns:1fr}.performance-filters>*{width:100%}}
</style>
